export function composeMiddleware(middlewares: Middleware[]): Middleware {
  return function composedMiddleware(event: H3Event, next: () => unknown | Promise<unknown>) {
    let index = 0;
    let nextCalled: undefined | boolean = undefined;
    let nextResult: unknown = undefined;

    function callNext() {
      if (nextCalled) {
        return nextResult;
      }
      nextCalled = true;
      if (index === middlewares.length) {
        return next();
      }
      const ret = middlewares[index](event, callNext);
      index++;
      return ret;
    }

    return callNext();
  };
}

